<?php require_once 'includes/admin_common.php'; $id=(int)($_GET['id']??0); if($id<1){flash('danger','Invalid user.');redirect_to('manage_ustads.php');} if($id===current_admin_id()){flash('warning','You cannot delete yourself.');redirect_to('manage_ustads.php');} $u=fetch_one('SELECT id,role FROM ustads WHERE id=?','i',[$id]); if(!$u){flash('danger','User not found.');redirect_to('manage_ustads.php');} if(strtoupper($u['role'])==='ADMIN'){ $cnt=fetch_one("SELECT COUNT(*) c FROM ustads WHERE UPPER(role)='ADMIN'"); if((int)($cnt['c']??0)<=1){flash('warning','Cannot delete the last ADMIN.');redirect_to('manage_ustads.php');}} execute_stmt('DELETE FROM ustads WHERE id=?','i',[$id]); flash('success','User deleted successfully.'); redirect_to('manage_ustads.php');
